Ext.define('BNK.view.HumanResource.hrd.HrdScyAply02MViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.HrdScyAply02M',

    /* 뷰 초기화 */
    initView: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        /*이전 탭 확인하여 버튼 숨김처리*/
        var preView = vm.getData('detail').detail.preView;

        if(preView == 'tabScyInfo'){ // 이전 탭이 사회공헌활동 내역인 경우
            // 신청취소 버튼 숨기기
            refs.btnScyApl.setHidden(true);
        }else{ 						  // 이전 탭이 사회공헌활동 신청인 경우

            var now = DateUtils.encodeDate(new Date(), 'Ymd'); // 현재일자

            /*신청상태를 확인하여 버튼 설정하기*/

            var aplStatus = vm.getData('detail').detail.aplStatus; // 사회공헌활동 신청테이블에서 신청한 row 개수. (0:신청가능, 1 :신청완료)
            var csrDt = vm.getData('detail').detail.csrDt; 		// 사회공헌 종료일자

            // 과거의 데이터인 경우
            if(Number(now) > Number(csrDt)){
                // 신청취소 버튼 숨기기
                refs.btnScyApl.setHidden(true);
                return;
            }

            if(aplStatus == '0'){
                refs.btnScyApl.setStyle('background-color:#000000;color:white;');
                refs.btnScyApl.setHtml('사회공헌활동 신청');
            }else{
                refs.btnScyApl.setHtml('사회공헌활동 취소');
            }
        }


    },

    /* utc to date string */
    dateTo8Char: function(utc) {
         if(utc){
             if (utc.toString().length > 8 && typeof (utc) != 'string') {
                 var yy = utc.getFullYear().toString();
                 var mm = (utc.getMonth() + 1).toString();
                 if (mm.length < 2) {
                     mm = '0' + mm;
                 }
                 var dd = utc.getDate().toString();
                 if (dd.length < 2) {
                     dd = '0' + dd;
                 }
                 return yy + mm + dd;
             }else if(utc.toString().length > 8){
                 return utc.replace('-', '').replace('-', '').substr(0, 8);
             }else {
                 return utc;
             }
         }
    },

    /* 신청 결과 알림창 콜백함수 */
    goBack: function(me) {
        var home = this.getView().up(Property.ROUTE_HOME),
            naviView = home.lookup('NaviView'),
            backButton = naviView.getNavigationBar().getBackButton();
        backButton.onTap();	// 뒤로가기
    },

    /* 신청취소 로직 */
    onCancel: function(btn,text) {
        if(btn != 'yes') return false;

                var me = this;
                var vm = me.getViewModel();
                var refs = me.getReferences();
                var data = vm.data.detail;

                // Service 호출
                Ext.Ajax.request({
                    headers : {
                        viewId : this.getView().xtype, 				// userAlias
                        serviceId : 'HrdScySvc.deleteHrdScyCtrbApl' // 신청자 row 삭제
                    },
                    jsonData : data,
                    scope : me,
                    success : function(response, opts) {
                        var result = Ext.JSON.decode(response.responseText); // 서버응답결과 JSON 변환

                        if(result.isApply === 0){  // 기존에 신청하지 않은 사용자는 서버단에서 UPDATE 하지 않음
                          Ext.Msg.show({
                              title : '미신청',
                              message : '아직 신청하지 않으셨습니다.',
                              buttons : Ext.MessageBox.YES,
                              fn: function(btn){}
                          });
                          return false;
                        }

                        if(result.getPointed == 1){ // 획득한 포인트가 있는 경우 삭제 불가
                          Ext.Msg.show({
                              title : '취소불가',
                              message : '포인트를 획득하여 취소할 수 없습니다.',
                              buttons : Ext.MessageBox.YES,
                              fn: function(btn){}
                          });
                          return false;
                        }

                        // 취소 완료 시 목록으로
                        Ext.Msg.show({
                            title : '신청 취소',
                            message : '신청 취소되었습니다.',
                            buttons : Ext.MessageBox.YES,
                            fn: function(btn){
                                if(btn === 'yes'){
                                    me.goBack(me);
                                }
                            }
                        });
                    },
                    failure : function(response, opts){
                        // Service 실패 했을 경우 기능
                        Ext.Msg.show({
                            title : '실패',
                            message : '취소 도중 에러가 발생했습니다.',
                            buttons : Ext.MessageBox.YES,
                            fn: function(btn){
                                if(btn === 'yes'){
                                    me.goBack(me);
                                }
                            }
                        });
                    }
                });
    },

    /* 사회공헌활동 신청/취소 버튼 클릭 이벤트 */
    onBtnAplyLineTap: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var data = vm.data.detail;
        var aplStatus = data.aplStatus; // 신청 row 개수 (0:신청가능, 1:신청완료)

        if(aplStatus == '0'){ // 신청 로직
            if ( me.dateTo8Char(new Date()) > data.cltEdt ){
                Ext.Msg.show({
                    title : '신청불가',
                    message : '모집기간이 종료되었습니다.',
                    buttons : Ext.MessageBox.YES,
                    fn: function(btn){}
                });
                return false;
            } else if ( data.cltStrdt > me.dateTo8Char(new Date()) ) {
                Ext.Msg.show({
                    title : '신청불가',
                    message : '모집기간이 아닙니다.',
                    buttons : Ext.MessageBox.YES,
                    fn: function(btn){}
                });
                return false;
            }

            data.hrHrdmCsrId = data.id;
            data.csrAplStcd = '01'; // 최초 신청 시 신청상태 = 신청
            data.stcd = Constants.stcd.NORMAL; // 최초 신청 시 상태 = 정상
            if(data.csrAmt){
                for(var i in data.csrAmt){
                    data.csrAmt = data.csrAmt.replace(',', '');  // , 빼기
                }
            }

            // Service 호출
            Ext.Ajax.request({
                headers : {
                    viewId : this.getView().xtype, // userAlias
                    serviceId : 'HrdScySvc.insertHrdScyCtrbApl'
                },
                jsonData : data,
                scope : me,
                success : function(response, opts) {
                    var result = Ext.JSON.decode(response.responseText); // 서버응답결과 JSON 변환

                    if(result.isApply === 1){
                        Ext.Msg.show({
                            title : '중복 신청',
                            message : '이미 신청을 하셨습니다.',
                            buttons : Ext.MessageBox.YES,
                            fn: function(btn){
                                if(btn === 'yes'){
                                    me.goBack(me);
                                }
                            }
                        });
                    } else {
                        Ext.Msg.show({
                            title : '신청 완료',
                            message : '정상 신청 되었습니다.',
                            buttons : Ext.MessageBox.YES,
                            fn: function(btn){
                                if(btn === 'yes'){
                                    me.goBack(me);
                                }
                            }
                        });
                    }
                },
                failure : function(response, opts){
                    // Service 실패 했을 경우 기능
                    Ext.Msg.show({
                        title : '실패',
                        message : '신청 도중 에러가 발생했습니다.',
                        buttons : Ext.MessageBox.YES,
                        fn: function(btn){
                            if(btn === 'yes'){
                                me.goBack(me);
                            }
                        }
                    });
                }
            });

        }else{ // 신청 취소 로직
            Ext.Msg.confirm('신청취소', '정말로 취소 하시겠습니까?', me.onCancel, me);
        }
    },

    /* 뷰 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            initConfig = component.config,
            data = initConfig.records[0].data;

        vm.set('detail', data);
        vm.set('detail.viewId', Ext.id());
        vm.set('detail.crud', 'C');

        me.initView();
    }

});